<?php
/** Reversible preference security checks on the local test site. */
function preference_check($ok,$message){if(!$ok)throw new Exception($message);echo 'PASS '.$message.PHP_EOL;}
function preference_call($method,$body=[]){$r=new WP_REST_Request($method,'/looper-for-etch/v1/preferences');if($method==='POST'){$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($body));}return rest_do_request($r);}
wp_set_current_user(1);$before=[];foreach(['lfe_autocomplete_','lfe_direct_actions_']as$prefix){$key=$prefix.get_current_blog_id();$before[$key]=['exists'=>metadata_exists('user',1,$key),'value'=>get_user_meta(1,$key,true)];}
try{wp_set_current_user(0);preference_check(preference_call('GET')->get_status()===401,'Anonymous preference access denied');preference_check(preference_call('POST',['autocomplete'=>true])->get_status()===401,'Anonymous preference save denied');wp_set_current_user(1);preference_check(preference_call('POST',['autocomplete'=>'true'])->get_status()===400,'Non-boolean preference rejected');preference_check(preference_call('POST',['unrelated_meta'=>true])->get_status()===400,'Unknown preference rejected');preference_check(preference_call('POST',['autocomplete'=>true])->get_data()['autocomplete']===true,'Enable autocomplete saved');preference_check(lfe_autocomplete_enabled(),'Autocomplete readback enabled');preference_check(preference_call('POST',['autocomplete'=>false])->get_data()['autocomplete']===false,'Disable autocomplete saved');preference_check(preference_call('POST',['directActions'=>true])->get_data()['directActions']===true,'Direct actions opt-in saved');preference_check(preference_call('POST',['directActions'=>false])->get_data()['directActions']===false,'Direct actions disabled');}finally{foreach($before as$key=>$data){if($data['exists'])update_user_meta(1,$key,$data['value']);else delete_user_meta(1,$key);}}
